SET NAMES utf8mb4;
-- Guida di «Marketing»: ora spiega tutto nel popup «?» (la pagina Studio non ha più la finestra «Come funziona» separata). Si può rieseguire (ON DUPLICATE KEY UPDATE). Richiede la 2026_11_29.
INSERT INTO page_help (page_key, title, body, more, sort_order) VALUES
('dashboard_marketing', 'Marketing', 'Progetti di marketing a passi, riutilizzabili: li esegui tu o li fai eseguire a un assistente AI via MCP.', 'Un **progetto** è un modello: una serie di passi (Passo 1, Passo 2…) chiusa dal **Finale**, ognuno con titolo e istruzioni. Ogni volta che lo usi («Esegui ora», oppure un''IA via MCP) nasce un''**esecuzione**: i passi si completano in ordine e la **Cronologia** registra giorno, ora, chi (Utente o IA) e le note. L''interruttore **Attivo** decide se il progetto si può usare. Ogni progetto ha un **ID** (es. ID 12): è lo stesso numero che usano le IA, così puoi passarlo a un''altra IA per farle continuare il lavoro. Le IA non possono eliminare progetti o passi: l''eliminazione si fa solo da qui. Strumenti MCP: list_marketing_projects, get_marketing_project, create_marketing_project, update_marketing_project, add_marketing_step, update_marketing_step, start_marketing_run, add_marketing_note, complete_marketing_step, interrupt_marketing_run, list_marketing_runs, get_marketing_run.', 1180)
ON DUPLICATE KEY UPDATE title = VALUES(title), body = VALUES(body), more = VALUES(more);
